import readline from 'node:readline/promises';
import {Writable} from 'node:stream';
import {hashPassword} from '../src/web/security.js';
// Suppress typed characters, including terminal echo generated by readline.
const muted=new Writable({write(_chunk,_encoding,cb){cb();}});
const rl=readline.createInterface({input:process.stdin,output:muted,terminal:true});
process.stdout.write('Dashboard password (12+ characters, input hidden): ');
try{const p=await rl.question('');process.stdout.write('\nBA_BIAS_WEB_PASSWORD_HASH='+await hashPassword(p)+'\n');}catch(e){console.error(e.message);process.exitCode=1;}finally{rl.close();}
